INSERT INTO `planificacoes` VALUES ('01a15e0e-f194-7185-b2a9-dec258fa3a6f','01a0abb0-60f9-7152-a17a-c3b40c00a83a','01a0abf2-cbec-7353-a246-cbba5d3a4515','01a0aba1-2f6f-7202-a80a-5965c463f34b','01a0aba0-ada4-738e-b5ff-0a335667654e','01a0abb0-5f98-7245-be23-50e8f6bec443','1º Trimestre','PLANIFICAÇÃO DIDÁCTICA PROPOSTA 10.ª CLASSE','Técnicas e Linguagens de Programação (TLP) – Python I.º TRIMESTRE 2026 / 2027\r\n\r\nA presente planificação procura estabelecer uma base sólida para a continuidade da formação \r\ndos estudantes nas classes subsequentes, preparando-os não apenas para aprender novas \r\nlinguagens e tecnologias, mas, sobretudo, para pensar de forma estruturada, resolver \r\nproblemas e utilizar a programação como instrumento de transformação de necessidades \r\nem soluções informáticas concretas. \r\nA mesma tem como Objectivo Geral:  \r\nDesenvolver o raciocínio lógico, o pensamento computacional e as competências básicas de \r\nprogramação dos alunos, capacitando-os em analise de problemas, elaboração de algoritmos e \r\ndesenvolvimento de soluções práticas em Python, através da resolução progressiva de \r\nproblemas reais relacionados com o contexto escolar, pessoal e profissional.',1,'01a0abb0-61fb-70c2-99b5-29ee21a15773','2026-10-21 11:43:20','2026-10-21 11:43:20');
/*!40000 ALTER TABLE `planificacoes` ENABLE KEYS */;
UNLOCK TABLES;

