INSERT INTO `sugestoes_temas_pap` VALUES ('01a11a36-cdb3-7137-aacc-e44269b3b17c','01a0abf2-cbec-7353-a246-cbba5d3a4515',NULL,'Desenvolvimento de um Sistema de Acompanhamento e Avaliação da PAP','O sistema poderia:\n•	registar estudantes;\n•	atribuir orientadores;\n•	gerir temas;\n•	acompanhar etapas;\n•	controlar prazos;\n•	analisar documentos;\n•	detectar problemas de estrutura e das normas APA/ABNT;\n•	gerar indicadores;\n•	permitir perguntas à IA sobre o projecto;\n•	auxiliar na elaboração de cronogramas;\n•	gerar relatórios para coordenação;\n•	Detenção de plágio.',1,'pendente',NULL,NULL,NULL,'2026-10-08 07:32:41','2026-10-08 07:32:41'),('01a11a6a-159b-72c6-8aea-95fa264fd724','01a0abf2-cbec-7353-a246-cbba5d3a4515',NULL,'Plataforma de Oportunidades de Emprego e Formação Para Jovens','Criar uma plataforma onde jovens registam competências, formação e experiência e empresas registam oportunidades. Um mecanismo inteligente deverá fazer a correspondência entre perfis e oportunidades.',1,'pendente',NULL,NULL,NULL,'2026-10-08 08:28:42','2026-10-08 08:28:42'),('01a11a6c-5669-71e2-a56c-4d638549d457','01a0abf2-cbec-7353-a246-cbba5d3a4515',NULL,'Sistema Inteligente de Gestão e Encaminhamento de Reclamações sobre Serviços Públicos','Permitir que cidadãos comuniquem problemas relacionados com serviços públicos. O sistema deverá classificar, encaminhar e acompanhar as reclamações, gerando indicadores para as instituições responsáveis.',1,'pendente',NULL,NULL,NULL,'2026-10-08 08:31:10','2026-10-08 08:31:10'),('01a11a84-e9f2-7068-8257-4eef12f24427','01a0abf2-cbec-7353-a246-cbba5d3a4515',NULL,'Plataforma de Ligação entre Pequenos Produtores Agrícolas e Mercados','Permitir aos agricultores divulgar produtos, quantidades e localização, enquanto compradores consultam a oferta. O sistema poderá fornecer informações sobre procura e oportunidades de comercialização.',1,'pendente',NULL,NULL,NULL,'2026-10-08 08:58:00','2026-10-08 08:58:00'),('01a11a91-2227-73f4-9a0f-589d4c6137a6','01a0abf2-cbec-7353-a246-cbba5d3a4515',NULL,'Plataforma de Partilha e Reutilização de Equipamentos Informáticos','Criar um sistema que permita doar, recuperar e redistribuir computadores e outros equipamentos a estudantes ou instituições que deles necessitem.',1,'pendente',NULL,NULL,NULL,'2026-10-08 09:11:21','2026-10-08 09:11:21'),('01a11a92-c80a-70dc-bbe0-2c9123d4773d','01a0abf2-cbec-7353-a246-cbba5d3a4515',NULL,'Sistema Inteligente de Gestão de Filas e Atendimento em Serviços Públicos','Organizar o atendimento através de senhas digitais, previsão do tempo de espera e acompanhamento do fluxo de utentes, procurando reduzir filas e melhorar a experiência do cidadão.',1,'pendente',NULL,NULL,NULL,'2026-10-08 09:13:09','2026-10-08 09:13:09');
